sp_widget.client_script:
function DeliveryPartnerReportingCtrl() {
    var c = this;

    c.form = {
        incident_type: '',
        severity: 'medium',
        dark_store: '',
        description: '',
        order_number: ''
    };
    c.submitting = false;

    c.incidentTypes = [
        { value: 'order_not_ready', label: 'Order Not Ready at Pickup' },
        { value: 'wrong_items_packed', label: 'Wrong Items Packed' },
        { value: 'unsafe_store_conditions', label: 'Unsafe Store Conditions' },
        { value: 'customer_unreachable', label: 'Customer Unreachable / Unavailable' },
        { value: 'app_navigation_issue', label: 'App / Navigation Issue' },
        { value: 'harassment_safety', label: 'Harassment or Safety Concern' },
        { value: 'vehicle_breakdown', label: 'Vehicle Breakdown' },
        { value: 'other', label: 'Other' }
    ];

    c.submitIncident = function () {
        if (!c.form.dark_store || !c.form.incident_type) {
            return;
        }
        c.submitting = true;
        c.data.action = 'submit_incident';
        c.data.dark_store = c.form.dark_store;
        c.data.incident_type = c.form.incident_type;
        c.data.severity = c.form.severity;
        c.data.description = c.form.description;
        c.data.order_number = c.form.order_number;

        c.server.update().then(function (response) {
            c.submitting = false;
            c.form = { incident_type: '', severity: 'medium', dark_store: '', description: '', order_number: '' };
        });
    };
}

sp_widget.css:
.qcops-dp-widget {
    max-width: 480px;
    margin: 0 auto;

    .panel-heading h3 {
        margin: 0;
        font-size: 18px;
    }

    table.table-condensed td,
    table.table-condensed th {
        padding: 4px 8px;
        font-size: 12px;
    }
}

sp_widget.script:
(function () {
    data.darkStores = [];
    var storeGr = new GlideRecord('x_2145749_qc_dark_store');
    storeGr.addQuery('status', 'active');
    storeGr.orderBy('store_name');
    storeGr.query();
    while (storeGr.next()) {
        data.darkStores.push({ value: storeGr.getUniqueValue(), label: storeGr.getValue('store_name') });
    }

    var partnerGr = new GlideRecord('x_2145749_qc_delivery_partner');
    partnerGr.addQuery('user', gs.getUserID());
    partnerGr.query();
    data.partnerFound = partnerGr.next();

    if (data.partnerFound) {
        data.partnerSysId = partnerGr.getUniqueValue();
        data.partnerName = partnerGr.getValue('partner_name');

        if (input && input.action === 'submit_incident') {
            var newInc = new GlideRecord('x_2145749_qc_partner_incident');
            newInc.initialize();
            newInc.setValue('partner', data.partnerSysId);
            newInc.setValue('dark_store', input.dark_store);
            newInc.setValue('incident_type', input.incident_type);
            newInc.setValue('severity', input.severity);
            newInc.setValue('description', input.description);
            newInc.setValue('order_number', input.order_number);
            newInc.setValue('reported_at', new GlideDateTime().getDisplayValue());
            newInc.insert();
            data.submitted = true;
            data.submittedNumber = newInc.getValue('number');
        }

        var myIncidents = [];
        var incGr = new GlideRecord('x_2145749_qc_partner_incident');
        incGr.addQuery('partner', data.partnerSysId);
        incGr.orderByDesc('sys_created_on');
        incGr.setLimit(10);
        incGr.query();
        while (incGr.next()) {
            myIncidents.push({
                number: incGr.getValue('number'),
                type: incGr.getDisplayValue('incident_type'),
                severity: incGr.getDisplayValue('severity'),
                state: incGr.getDisplayValue('state'),
                created: incGr.getDisplayValue('sys_created_on')
            });
        }
        data.myIncidents = myIncidents;
    }
})();
